import AppKit

/// Keeps the Dock icon in the active theme's colors. Each theme other
/// than System ships a recolored icon in the bundle's Resources
/// (`AppIcon-<Theme>.png`, generated by scripts/recolor-app-icon.swift and
/// copied in by `make mac-app`); System restores the bundle's own icon.
///
/// This sets the running app's Dock icon only. Finder and Launchpad keep
/// showing the bundle icon, which macOS reads from the app on disk.
enum DockIconSync {
    static func resourceName(forThemeID id: String) -> String? {
        switch id {
        case "sage": return "AppIcon-Sage"
        case "clay": return "AppIcon-Clay"
        case "slate": return "AppIcon-Slate"
        case "aubergine": return "AppIcon-Aubergine"
        case "nordic": return "AppIcon-Nordic"
        default: return nil
        }
    }

    @MainActor
    static func apply(themeID: String) {
        // nil hands the Dock back the bundle icon. Also the outcome when
        // the image is missing, as under `swift run`, which builds no
        // bundle to hold it.
        NSApplication.shared.applicationIconImage = resourceName(forThemeID: themeID)
            .flatMap { Bundle.main.url(forResource: $0, withExtension: "png") }
            .flatMap(NSImage.init(contentsOf:))
    }
}
